import unittest
from solution import to_roman

class T(unittest.TestCase):
    def test_small(self):
        self.assertEqual(to_roman(1), "I")
        self.assertEqual(to_roman(4), "IV")
        self.assertEqual(to_roman(9), "IX")
    def test_mid(self):
        self.assertEqual(to_roman(58), "LVIII")
        self.assertEqual(to_roman(1994), "MCMXCIV")
    def test_max(self):
        self.assertEqual(to_roman(3999), "MMMCMXCIX")
    def test_range(self):
        for bad in (0, -1, 4000):
            with self.assertRaises(ValueError):
                to_roman(bad)

import unittest
from solution import first_free

class T(unittest.TestCase):
    def test_empty_day(self):
        self.assertEqual(first_free([], 60), 540)
    def test_gap_after_first(self):
        self.assertEqual(first_free([(540, 600)], 30), 600)
    def test_unsorted_and_overlapping(self):
        busy = [(660, 720), (540, 600), (570, 690)]
        self.assertEqual(first_free(busy, 30), 720)
    def test_exact_fit(self):
        self.assertEqual(first_free([(540, 600), (630, 1080)], 30), 600)
    def test_too_small(self):
        self.assertIsNone(first_free([(540, 600), (620, 1080)], 30))
    def test_none_when_full(self):
        self.assertIsNone(first_free([(540, 1080)], 10))
    def test_ignores_outside_hours(self):
        self.assertEqual(first_free([(0, 540)], 60), 540)

const assert = require("assert");
const { diff } = require("./solution.js");
assert.deepStrictEqual(diff({a: 1}, {a: 1}), {added: {}, removed: {}, changed: {}});
assert.deepStrictEqual(diff({a: 1}, {a: 2}), {added: {}, removed: {}, changed: {a: [1, 2]}});
assert.deepStrictEqual(diff({}, {b: 3}), {added: {b: 3}, removed: {}, changed: {}});
assert.deepStrictEqual(diff({c: 4}, {}), {added: {}, removed: {c: 4}, changed: {}});
// an undefined value is still a present key, so this is "changed", not "added"
assert.deepStrictEqual(diff({d: undefined}, {d: 1}),
                       {added: {}, removed: {}, changed: {d: [undefined, 1]}});
// ...and dropping to undefined is a change, not a removal
assert.deepStrictEqual(diff({e: 1}, {e: undefined}),
                       {added: {}, removed: {}, changed: {e: [1, undefined]}});
const before = {f: 1};
diff(before, {f: 2});
assert.deepStrictEqual(before, {f: 1}, "must not mutate inputs");
console.log("ok");

