package main

import (
	"sync/atomic"
	"testing"
)

func TestOrder(t *testing.T) {
	in := []int{1, 2, 3, 4, 5, 6, 7, 8}
	got := MapConcurrent(in, 3, func(x int) int { return x * 10 })
	for i, v := range in {
		if got[i] != v*10 {
			t.Fatalf("index %d: got %d want %d", i, got[i], v*10)
		}
	}
}

func TestLimitRespected(t *testing.T) {
	var cur, max int64
	f := func(x int) int {
		n := atomic.AddInt64(&cur, 1)
		for {
			m := atomic.LoadInt64(&max)
			if n <= m || atomic.CompareAndSwapInt64(&max, m, n) {
				break
			}
		}
		for i := 0; i < 200000; i++ {
			_ = i
		}
		atomic.AddInt64(&cur, -1)
		return x
	}
	MapConcurrent(make([]int, 50), 4, f)
	if atomic.LoadInt64(&max) > 4 {
		t.Fatalf("concurrency %d exceeded limit 4", max)
	}
}

func TestZeroLimit(t *testing.T) {
	got := MapConcurrent([]int{1, 2}, 0, func(x int) int { return x })
	if len(got) != 2 {
		t.Fatalf("got %v", got)
	}
}

func TestEmpty(t *testing.T) {
	if got := MapConcurrent(nil, 2, func(x int) int { return x }); len(got) != 0 {
		t.Fatalf("got %v", got)
	}
}

const assert = require("assert");
const { page } = require("./solution.js");
const rows = [1,2,3,4,5].map(id => ({id, v: `v${id}`}));
let r = page(rows, null, 2);
assert.deepStrictEqual(r.items.map(x => x.id), [1,2]);
assert.strictEqual(r.nextCursor, 2);
r = page(rows, 2, 2);
assert.deepStrictEqual(r.items.map(x => x.id), [3,4]);
assert.strictEqual(r.nextCursor, 4);
r = page(rows, 4, 2);
assert.deepStrictEqual(r.items.map(x => x.id), [5]);
assert.strictEqual(r.nextCursor, null, "last page has no next cursor");
r = page(rows, 5, 2);
assert.deepStrictEqual(r.items, []);
assert.strictEqual(r.nextCursor, null);
r = page(rows, 99, 2);
assert.deepStrictEqual(r.items, []);
assert.strictEqual(r.nextCursor, null);
assert.throws(() => page(rows, null, 0), RangeError);
console.log("ok");
